{"packet_id":"D010-01","doc_id":"D010","jurisdiction":"Boston, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Boston Fair Chance criminal record screening policy","requirement":"Housing providers may not impose a blanket denial based on arrests or convictions; they must exclude non-convictions, sealed, expunged and juvenile records and convictions older than 5 years, and review applicants case by case.","key_value":"No blanket denial; convictions older than 5 years excluded","coverage_conditions":"Housing providers receiving Department of Neighborhood Development funding and/or land, or holding income-restricted units created under the BPDA Inclusionary Development Policy; also applied to the Office of Fair Housing and Equity Affirmative Marketing Program.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Housing providers receiving DND funding/land or with BPDA inclusionary income-restricted units"},"exemptions":"Policy does not apply where there is a direct relationship between the conviction and the housing sought or an unreasonable risk of substantial harm, or to current criminal behavior; federal or state criminal history requirements that conflict preempt the policy.","penalty":null,"effective_date":"2017-02","citation":"Boston Fair Chance Tenant Selection Policy","quoted_span":"Housing providers receiving Department of Neighborhood Development (DND) funding and/or
land, or that have income restricted units created under the Boston Planning and Development
Agency (BPDA) Inclusionary Development Policy will not impose a blanket policy that denies
housing to anyone with arrests and or convictions. Housing providers will consider applicants on
a case-by-case basis.","interaction":"Federal or state law imposing a conflicting criminal history requirement preempts this policy.","confidence":0.75,"conflict_flag":true,"conflict_note":"The policy itself states that conflicting federal or state criminal history requirements preempt it."}
{"packet_id":"D010-01","doc_id":"D010","jurisdiction":"Boston, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Boston Fair Chance credit screening restriction","requirement":"The agent may not use an applicant's credit score to approve or deny housing; credit history may be considered only in lieu of rental history to judge ability to pay, and lack of credit history alone is not justification to reject.","key_value":"Credit-score denial prohibited","coverage_conditions":"Housing providers receiving Department of Neighborhood Development funding and/or land, or holding income-restricted units created under the BPDA Inclusionary Development Policy; also applied to the Office of Fair Housing and Equity Affirmative Marketing Program.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Housing providers receiving DND funding/land or with BPDA inclusionary income-restricted units"},"exemptions":null,"penalty":null,"effective_date":"2017-02","citation":"Boston Fair Chance Tenant Selection Policy","quoted_span":"The agent agrees not to use the applicant credit score to approve or deny housing","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
